(function() {
  function generateMap(canvasId) {
    const canvas = document.getElementById(canvasId);
    if (!canvas) return;
    canvas.width = canvas.height = 500;
    const ctx = canvas.getContext('2d');
    const GRID_SIZE = 100, CELL_SIZE = canvas.width / GRID_SIZE;
    const MIN_ROOM_SIZE = 6;
    const MAX_SPLITS = 4;

    // Create button if not exists
    if (!document.getElementById('genBtn')) {
      const btn = document.createElement('button');
      btn.id = 'genBtn';
      btn.textContent = 'Generate New Map';
      btn.style.marginTop = '10px';
      btn.onclick = () => generateMap(canvasId);
      document.body.appendChild(btn);
    }

    // Helper to create empty grid
    function initGrid() {
      const grid = [];
      for (let y = 0; y < GRID_SIZE; y++) {
        const row = new Array(GRID_SIZE).fill(0); // 0 wall
        grid.push(row);
      }
      return grid;
    }

    // Recursive BSP split
    function bspSplit(x, y, w, h, depth) {
      if (depth >= MAX_SPLITS || w < MIN_ROOM_SIZE * 2 || h < MIN_ROOM_SIZE * 2) {
        carveRoom(x, y, w, h);
        return;
      }
      const horizontal = Math.random() < 0.5;
      if (horizontal) {
        const split = Math.floor(Math.random() * (h - MIN_ROOM_SIZE * 2)) + MIN_ROOM_SIZE;
        bspSplit(x, y, w, split, depth + 1);
        bspSplit(x, y + split, w, h - split, depth + 1);
        connectRooms(
          { x: x, y: y + split - 1, w: w, h: split },
          { x: x, y: y + split, w: w, h: h - split }
        );
      } else {
        const split = Math.floor(Math.random() * (w - MIN_ROOM_SIZE * 2)) + MIN_ROOM_SIZE;
        bspSplit(x, y, split, h, depth + 1);
        bspSplit(x + split, y, w - split, h, depth + 1);
        connectRooms(
          { x: x + split - 1, y: y, w: split, h: h },
          { x: x + split, y: y, w: w - split, h: h }
        );
      }
    }

    // Carve a room inside area
    function carveRoom(x, y, w, h) {
      const roomW = Math.floor(Math.random() * (w - MIN_ROOM_SIZE)) + MIN_ROOM_SIZE;
      const roomH = Math.floor(Math.random() * (h - MIN_ROOM_SIZE)) + MIN_ROOM_SIZE;
      const roomX = x + Math.floor(Math.random() * (w - roomW));
      const roomY = y + Math.floor(Math.random() * (h - roomH));
      for (let i = roomY; i < roomY + roomH; i++) {
        for (let j = roomX; j < roomX + roomW; j++) {
          grid[i][j] = 1; // floor
        }
      }
      rooms.push({ x: roomX, y: roomY, w: roomW, h: roomH, cx: roomX + Math.floor(roomW / 2), cy: roomY + Math.floor(roomH / 2) });
    }

    // Connect two areas with corridor
    function connectRooms(a, b) {
      const pointA = new Array(rooms.length).find(r => r.cx >= a.x && r.cx < a.x + a.w && r.cy >= a.y && r.cy < a.y + a.h);
      const pointB = new Array(rooms.length).find(r => r.cx >= b.x && r.cx < b.x + b.w && r.cy >= b.y && r.cy < b.y + b.h);
      const ax = pointA ? pointA.cx : Math.floor((a.x + a.x + a.w) / 2);
      const ay = pointA ? pointA.cy : Math.floor((a.y + a.y + a.h) / 2);
      const bx = pointB ? pointB.cx : Math.floor((b.x + b.x + b.w) / 2);
      const by = pointB ? pointB.cy : Math.floor((b.y + b.y + b.h) / 2);

      let x = ax, y = ay;
      while (x !== bx) {
        grid[y][x] = 1;
        x += x < bx ? 1 : -1;
      }
      while (y !== by) {
        grid[y][x] = 1;
        y += y < by ? 1 : -1;
      }
    }

    // Flood-fill to ensure connectivity
    function isFullyConnected() {
      const visited = Array.from({ length: GRID_SIZE }, () => Array(GRID_SIZE).fill(false));
      const queue = [];
      let foundSpawn = false;
      for (let i = 0; i < GRID_SIZE; i++) {
        for (let j = 0; j < GRID_SIZE; j++) {
          if (grid[i][j] >= 1) {
            queue.push([i, j]);
            visited[i][j] = true;
            foundSpawn = true;
            break;
          }
        }
        if (foundSpawn) break;
      }
      let reachable = 0;
      while (queue.length) {
        const [y, x] = queue.shift();
        reachable++;
        const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
        for (const [dy, dx] of dirs) {
          const ny = y + dy, nx = x + dx;
          if (ny>=0 && ny<GRID_SIZE && nx>=0 && nx<GRID_SIZE && !visited[ny][nx] && grid[ny][nx] >= 1) {
            visited[ny][nx] = true;
            queue.push([ny, nx]);
          }
        }
      }
      let totalFloors = 0;
      for (let i = 0; i < GRID_SIZE; i++) for (let j = 0; j < GRID_SIZE; j++) if (grid[i][j] >= 1) totalFloors++;
      return reachable === totalFloors;
    }

    // Main generating loop
    let grid, rooms;
    while (true) {
      grid = initGrid();
      rooms = [];
      bspSplit(0, 0, GRID_SIZE, GRID_SIZE, 0);

      // Place spawn points
      for (let i = 0; i < 2; i++) {
        let y,x;
        do { y = Math.floor(Math.random() * GRID_SIZE); x = Math.floor(Math.random() * GRID_SIZE); } while (grid[y][x] !== 1);
        grid[y][x] = 2;
      }

      // Place weapon pickups
      for (let i = 0; i < 3; i++) {
        let y,x;
        do { y = Math.floor(Math.random() * GRID_SIZE); x = Math.floor(Math.random() * GRID_SIZE); } while (grid[y][x] !== 1);
        grid[y][x] = 3;
      }

      if (isFullyConnected()) break;
    }

    // Draw map
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let y = 0; y < GRID_SIZE; y++) {
      for (let x = 0; x < GRID_SIZE; x++) {
        switch (grid[y][x]) {
          case 0: ctx.fillStyle = '#000000'; break; // wall
          case 1: ctx.fillStyle = '#808080'; break; // floor
          case 2: ctx.fillStyle = '#00FF00'; break; // spawn
          case 3: ctx.fillStyle = '#FF0000'; break; // pickup
        }
        ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
      }
    }

    // Draw legend
    const legendX = 10, legendY = 10, legendW = 120, legendH = 70;
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(legendX, legendY, legendW, legendH);
    ctx.strokeStyle = '#000000';
    ctx.strokeRect(legendX, legendY, legendW, legendH);
    const items = [
      {color:'#000000', label:'Wall'},
      {color:'#808080', label:'Floor'},
      {color:'#00FF00', label:'Spawn'},
      {color:'#FF0000', label:'Weapon'}
    ];
    for (let i = 0; i < items.length; i++) {
      ctx.fillStyle = items[i].color;
      ctx.fillRect(legendX + 10, legendY + 10 + i*15, 12, 12);
      ctx.fillStyle = '#000000';
      ctx.font = '12px Arial';
      ctx.fillText(items[i].label, legendX + 30, legendY + 22 + i*15);
    }
  }

  // Expose function globally
  window.generateProceduralFPSMap = generateMap;
})();
